import{_ as l,a0 as n,w as p,s as d,ao as r,I as a,x as e,a1 as s,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"用开源搜索引擎定制你的互联网 | LCTT x X-CMD","titleTemplate":false,"description":"用开源搜索引擎定制你的互联网 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用开源搜索引擎定制你的互联网 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用开源搜索引擎定制你的互联网 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200207 Customize your internet with an open source search engine","title":"用开源搜索引擎定制你的互联网","tag":"202002","desc":""},"relativePath":"202002/20200207 Customize your internet with an open source search engine.md","filePath":"[post].md"}'),u={name:"202002/20200207 Customize your internet with an open source search engine.md"};function f(y,t,m,C,g,x){const o=n("Link");return p(),d("div",null,[t[32]||(t[32]=r('<h1 id="用开源搜索引擎定制你的互联网" tabindex="-1">用开源搜索引擎定制你的互联网 <a class="header-anchor" href="#用开源搜索引擎定制你的互联网" aria-label="Permalink to “用开源搜索引擎定制你的互联网”">​</a></h1><blockquote><p>上手开源的对等 Web 索引器 YaCy。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202002/19/103541la7erglz7oloa4ye.jpg" alt=""></p><p>很久以前，互联网很小，小到几个人就可以索引它们，这些人收集了所有网站的名称和链接，并按主题将它们分别列在页面或印刷书籍中。随着万维网网络的发展，形成了“网站环”形式，具有类似的内容、主题或敏感性的站点捆绑在一起，形成了通往每个成员的循环路径。环中任何站点的访问者都可以单击按钮以转到环中的下一个或上一个站点，以发现与其兴趣相关的新站点。</p><p>又过了一段时间，互联网似乎变得臃肿不堪了。每个人都在网络上，有很多冗余信息和垃圾邮件，多到让你无法找到任何东西。Yahoo 和 AOL、CompuServe 以及类似的服务各自采用了不同的方法来解决这个问题，但是直到谷歌出现后，现代的搜索模型才得以普及。按谷歌的做法，互联网应该通过搜索引擎进行索引、排序和排名。</p><h3 id="为什么选择开源替代品" tabindex="-1">为什么选择开源替代品？ <a class="header-anchor" href="#为什么选择开源替代品" aria-label="Permalink to “为什么选择开源替代品？”">​</a></h3><p>像谷歌和 DuckDuckGo 这样的搜索引擎显然是卓有成效的。你可能是通过搜索引擎访问的本站。尽管对于因主机没有选择遵循优化搜索引擎的最佳实践从而导致会内容陷入困境这件事仍存在争论，但用于管理丰富的文化、知识和轻率的信息（即互联网）的现代解决方案是冷冰冰的索引。</p>',7)),a("p",null,[t[1]||(t[1]=e("但是也许出于隐私方面的考虑，或者你希望为使互联网更加独立而做出贡献，你或许不愿意使用谷歌或 DuckDuckGo。如果你对此感兴趣，那么可以考虑参加 ",-1)),s(o,{href:"https://yacy.net/"},{default:i(()=>[...t[0]||(t[0]=[e("YaCy",-1)])]),_:1}),t[2]||(t[2]=e("，这是一个对等互联网索引器和搜索引擎。",-1))]),t[33]||(t[33]=a("h3",{id:"安装-yacy",tabindex:"-1"},[e("安装 YaCy "),a("a",{class:"header-anchor",href:"#安装-yacy","aria-label":"Permalink to “安装 YaCy”"},"​")],-1)),a("p",null,[t[5]||(t[5]=e("要安装并尝试 YaCy，请首先确保已安装 Java。如果你使用的是 Linux，则可以按照我的《",-1)),s(o,{href:"https://linux.cn/article-11614-1.html"},{default:i(()=>[...t[3]||(t[3]=[e("如何在 Linux 上安装 Java",-1)])]),_:1}),t[6]||(t[6]=e("》中的说明进行操作。如果你使用 Windows 或 MacOS，请从 ",-1)),s(o,{href:"https://adoptopenjdk.net/releases.html"},{default:i(()=>[...t[4]||(t[4]=[e("AdoptOpenJDK.net",-1)])]),_:1}),t[7]||(t[7]=e(" 获取安装程序。",-1))]),a("p",null,[t[9]||(t[9]=e("安装 Java 后，请根据你的平台",-1)),s(o,{href:"https://yacy.net/download_installation/"},{default:i(()=>[...t[8]||(t[8]=[e("下载安装程序",-1)])]),_:1}),t[10]||(t[10]=e("。",-1))]),t[34]||(t[34]=r('<p>如果你使用的是 Linux，请解压缩 tarball 并将其移至 <code>/opt</code> 目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo tar --extract --file  yacy_*z --directory /opt</span></span></code></pre></div><p>根据下载的安装程序的说明启动 YaCy。</p><p>在 Linux 上，启动在后台运行的 YaCy：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ /opt/startYACY.sh &amp;</span></span></code></pre></div><p>在 Web 浏览器中，导航到 <code>localhost:8090</code> 并进行搜索。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-startpage.jpg" alt="YaCy start page" title="YaCy start page"></p><h3 id="将-yacy-添加到你的地址栏" tabindex="-1">将 YaCy 添加到你的地址栏 <a class="header-anchor" href="#将-yacy-添加到你的地址栏" aria-label="Permalink to “将 YaCy 添加到你的地址栏”">​</a></h3><p>如果你使用的是 Firefox Web 浏览器，则只需单击几下，即可在 Awesome Bar（Mozilla 给 URL 栏起的名称）中将 YaCy 设置为默认搜索引擎。</p><p>首先，如果尚未显示，在 Firefox 工具栏中使专用搜索栏显示出来（你不必使搜索栏保持一直可见；只需要激活它足够长的时间即可添加自定义搜索引擎）。Firefox 右上角的“汉堡”菜单中的“自定义”菜单中提供了搜索栏。在 Firefox 工具栏上的搜索栏可见后，导航至 <code>localhost:8090</code>，然后单击刚添加的 Firefox 搜索栏中的放大镜图标。单击选项将 YaCy 添加到你的 Firefox 的搜索引擎中。</p><p><img src="https://opensource.com/sites/default/files/uploads/yacy-add-firefox.jpg" alt="Adding YaCy to Firefox" title="Adding YaCy to Firefox"></p><p>完成此操作后，你可以在 Firefox 首选项中将其标记为默认值，或者仅在 Firefox 搜索栏中执行的搜索中选择性地使用它。如果将其设置为默认搜索引擎，则可能不需要专用搜索栏，因为 Awesome Bar 也使用默认引擎，因此可以将其从工具栏中删除。</p><h3 id="对等搜索引擎如何工作" tabindex="-1">对等搜索引擎如何工作 <a class="header-anchor" href="#对等搜索引擎如何工作" aria-label="Permalink to “对等搜索引擎如何工作”">​</a></h3>',13)),a("p",null,[t[12]||(t[12]=e("YaCy 是一个开源的分布式搜索引擎。它是用 ",-1)),s(o,{href:"https://opensource.com/resources/java"},{default:i(()=>[...t[11]||(t[11]=[e("Java",-1)])]),_:1}),t[13]||(t[13]=e(" 编写的，因此可以在任何平台上运行，并且可以执行 Web 爬网、索引和搜索。这是一个对等（P2P）网络，因此每个运行 YaCy 的用户都将努力地不断跟踪互联网的变化情况。当然，没有单个用户能拥有整个互联网的完整索引，因为这将需要一个数据中心来容纳，但是该索引分布在所有 YaCy 用户中且是冗余的。它与 BitTorrent 非常相似（因为它使用分布式哈希表 DHT 来引用索引条目），只不过你所共享的数据是单词和 URL 关联的矩阵。通过混合哈希表返回的结果，没人能说出谁搜索了哪些单词，因此所有搜索在功能上都是匿名的。这是用于无偏见、无广告、未跟踪和匿名搜索的有效系统，你只需要使用它就加入了它。",-1))]),t[35]||(t[35]=a("h3",{id:"搜索引擎和算法",tabindex:"-1"},[e("搜索引擎和算法 "),a("a",{class:"header-anchor",href:"#搜索引擎和算法","aria-label":"Permalink to “搜索引擎和算法”"},"​")],-1)),t[36]||(t[36]=a("p",null,"索引互联网的行为是指将网页分成单个单词，然后将页面的 URL 与每个单词相关联。在搜索引擎中搜索一个或多个单词将获取与该查询关联的所有 URL。YaCy 客户端在运行时也是如此。",-1)),t[37]||(t[37]=a("p",null,[e("客户端要做的另一件事是为你的浏览器提供搜索界面。你可以将 Web 浏览器指向 "),a("code",null,"localhost:8090"),e(" 来搜索 YaCy，而不是在要搜索时导航到谷歌。你甚至可以将其添加到浏览器的搜索栏中（取决于浏览器的可扩展性），因此可以从 URL 栏中进行搜索。")],-1)),t[38]||(t[38]=a("h3",{id:"yacy-的防火墙设置",tabindex:"-1"},[e("YaCy 的防火墙设置 "),a("a",{class:"header-anchor",href:"#yacy-的防火墙设置","aria-label":"Permalink to “YaCy 的防火墙设置”"},"​")],-1)),t[39]||(t[39]=a("p",null,"首次开始使用 YaCy 时，它可能运行在“初级”模式下。这意味着你的客户端爬网的站点仅对你可用，因为其他 YaCy 客户端无法访问你的索引条目。要加入对等环境，必须在路由器的防火墙（或者你正在运行的软件防火墙）中打开端口 8090，这称为“高级”模式。",-1)),a("p",null,[t[15]||(t[15]=e("如果你使用的是 Linux，则可以在《",-1)),s(o,{href:"https://opensource.com/article/19/7/make-linux-stronger-firewalls"},{default:i(()=>[...t[14]||(t[14]=[e("使用防火墙让你的 Linux 更加强大",-1)])]),_:1}),t[16]||(t[16]=e("》中找到有关计算机防火墙的更多信息。在其他平台上，请参考操作系统的文档。",-1))]),t[40]||(t[40]=r('<p>互联网服务提供商（ISP）提供的路由器上几乎总是启用了防火墙，并且有太多种类的防火墙无法准确说明。大多数路由器都提供了在防火墙上“打洞”的选项，因为许多流行的联网游戏都需要双向流量。</p><p>如果你知道如何登录路由器（通常为 192.168.0.1 或 10.1.0.1，但可能因制造商的设置而异），则登录并查找配置面板来控制“防火墙”或“端口转发”或“应用”。</p><p>找到路由器防火墙的首选项后，将端口 8090 添加到白名单。例如：</p><p><img src="https://opensource.com/sites/default/files/uploads/router-add-app.jpg" alt="Adding YaCy to an ISP router" title="Adding YaCy to an ISP router"></p><p>如果路由器正在进行端口转发，则必须使用相同的端口将传入的流量转发到计算机的 IP 地址。例如：</p><p><img src="https://opensource.com/sites/default/files/uploads/router-add-app1.jpg" alt="Adding YaCy to an ISP router" title="Adding YaCy to an ISP router"></p><p>如果由于某种原因无法调整防火墙设置，那也没事。YaCy 将继续以初级模式运行并作为对等搜索网络的客户端运行。</p><h3 id="你的互联网" tabindex="-1">你的互联网 <a class="header-anchor" href="#你的互联网" aria-label="Permalink to “你的互联网”">​</a></h3><p>使用 YaCy 搜索引擎可以做的不仅仅是被动搜索。你可以强制抓取不太显眼的网站，可以请求对网站进行网络抓取，可以选择使用 YaCy 进行本地搜索等等。你可以更好地控制<em>你的</em>互联网的所呈现的一切。高级用户越多，索引的网站就越多。索引的网站越多，所有用户的体验就越好。加入吧！</p><hr>',10)),a("p",null,[t[18]||(t[18]=e("via: ",-1)),s(o,{href:"https://opensource.com/article/20/2/open-source-search-engine"},{default:i(()=>[...t[17]||(t[17]=[e("https://opensource.com/article/20/2/open-source-search-engine",-1)])]),_:1})]),a("p",null,[t[23]||(t[23]=e("作者：",-1)),s(o,{href:"https://opensource.com/users/seth"},{default:i(()=>[...t[19]||(t[19]=[e("Seth Kenlon",-1)])]),_:1}),t[24]||(t[24]=e(" 选题：",-1)),s(o,{href:"https://github.com/lujun9972"},{default:i(()=>[...t[20]||(t[20]=[e("lujun9972",-1)])]),_:1}),t[25]||(t[25]=e(" 译者：",-1)),s(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[21]||(t[21]=[e("wxy",-1)])]),_:1}),t[26]||(t[26]=e(" 校对：",-1)),s(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[22]||(t[22]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[29]||(t[29]=e("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[27]||(t[27]=[e("LCTT",-1)])]),_:1}),t[30]||(t[30]=e(" 原创编译，",-1)),s(o,{href:"https://linux.cn/"},{default:i(()=>[...t[28]||(t[28]=[e("Linux中国",-1)])]),_:1}),t[31]||(t[31]=e(" 荣誉推出",-1))])])}const T=l(u,[["render",f]]);export{k as __pageData,T as default};
